// Phase 5 (PHASE-5-IMPLEMENTATION-PLAN.md Wave 1): single-condition,
// single-action evaluation -- the same scope app/rules/page.tsx's builder
// (and POST /api/rules/preview) actually supports today. Runs once per
// enabled-rule item from 'Read matching rules' -- '.item' (not '.first()')
// is deliberate here: unlike triage-pipeline.json's single-email items,
// multiple rules genuinely can be in flight in the same execution, and
// each must resolve against its OWN paired-item lineage downstream, not
// always the first one (see learnings.md L6 for the case where '.first()'
// was the right call instead -- opposite situation, single item always).
const email = $('Read email').first().json;
const rule = $json;

function fieldMatches(condition, email) {
  const { field, operator, value } = condition;
  switch (field) {
    case 'Sender domain': {
      const participants = email.participants || [];
      const from = participants.find((p) => p.role === 'from');
      const address = from ? from.address : '';
      return operator === 'equals' ? address === value : address.includes(value);
    }
    case 'Subject': {
      const subject = email.subject || '';
      return operator === 'equals' ? subject === value : subject.toLowerCase().includes(String(value).toLowerCase());
    }
    case 'Category': {
      const platform = email.platform || '';
      return operator === 'equals' ? platform === value : platform.toLowerCase().includes(String(value).toLowerCase());
    }
    case 'Confidence': {
      const confidence = email.confidence;
      if (confidence === null || confidence === undefined) return false;
      const n = Number(value);
      if (Number.isNaN(n)) return false;
      return operator === 'is above' ? confidence > n : confidence < n;
    }
    case 'Has attachment': {
      const attachments = email.attachments || [];
      return Array.isArray(attachments) && attachments.length > 0;
    }
    default:
      return false;
  }
}

const conditions = Array.isArray(rule.conditions) ? rule.conditions : [];
const condition = conditions[0];
const conditionMatched = condition ? fieldMatches(condition, email) : false;

const underCap = rule.daily_cap === null || rule.daily_cap === undefined || rule.run_count_today < rule.daily_cap;

const actions = Array.isArray(rule.actions) ? rule.actions : [];
// 'Auto-label' has no target value the builder ever collects (see the
// plan's Wave 1 note) -- it matches the same as any other action type
// here, but 'Route by action' below has no output for it, so it simply
// runs no further, writes no rule_runs row, and logs nothing.
const actionType = actions[0] ? actions[0].type : null;

return {
  json: {
    ruleId: rule.rule_id,
    emailId: email.id,
    actionType,
    matched: conditionMatched && underCap && actionType !== null,
    conditionSummary: rule.condition_summary,
    actionSummary: rule.action_summary,
  },
};
